    for (int i = n - 1; i >= 0; i--) {
        for (int j = m - 1; j >= 0; j--) {
            if (i == n - 1 && j == m - 1) {
                dp[i][j] = 0;
                continue;
            }

            // (i + j) 为偶数 -> Alice 操作
            if ((i + j) % 2 == 0) {
                int best = INT_MIN;

                // 向下走
                if (i + 1 < n) {
                    int score = (grid[i + 1][j] == '1' ? 1 : -1);
                    best = max(best, dp[i + 1][j] + score);
                }

                // 向右走
                if (j + 1 < m) {
                    int score = (grid[i][j + 1] == '1' ? 1 : -1);
                    best = max(best, dp[i][j + 1] + score);
                }

                dp[i][j] = best;
            }
            // (i + j) 为奇数 -> Bob 操作
            else {
                int best = INT_MAX;

                if (i + 1 < n) {
                    int score = (grid[i + 1][j] == '1' ? 1 : -1);
                    best = min(best, dp[i + 1][j] - score);
                }

                if (j + 1 < m) {
                    int score = (grid[i][j + 1] == '1' ? 1 : -1);
                    best = min(best, dp[i][j + 1] - score);
                }

                dp[i][j] = best;
            }
        }
    }

    return dp[0][0];
}

int main() {
    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (int i = 0; i < n; i++) {
        cin >> grid[i];
    }

    cout << solve(n, m, grid) << "\n";
    return 0;
}
